// فصل 01 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 01 of the book — converted from the HTML edition; generated file.

export const n = 1;
export const num = "01";
export const title = "معرفی Git و نقشه راه ۲۰۲۶ — از صفر تا Senior";
export const label = "فصل ۱ · معرفی Git و نقشه راه";
export const part = 0;
export const html = "<p class=\"lead\">Git ابزار ثبت تاریخچهٔ کد است؛ هر کامیت یک عکس کامل از پروژه در آن لحظه است. VS Code و GitHub ظاهر این ابزارند — مغز کار همان Git روی رایانهٔ توست.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری این فصل</span></span></h2>\n<p class=\"keep-next\">بعد از این فصل، بدون ابهام می‌توانی بگویی:</p>\n<ul>\n<li>Git چیست (برنامه روی رایانهٔ تو) و GitHub چیست (سایت میزبانی)</li>\n<li>چرا به‌جای کپی‌کردن پوشه، از Git استفاده می‌کنیم</li>\n<li>کامیت، شاخه و «عکس لحظه‌ای» یعنی چه</li>\n<li>این کتاب را با چه ترتیبی بخوانی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🤔 چرا Git مهارت شغلی است؟</span></span></h2>\n<p>در آگهی‌های ۲۰۲۶ تقریباً هیچ نقش نرم‌افزاری بدون Git وجود ندارد. اما شرکت‌های خوب دیگر نمی‌پرسند «تفاوت <code>pull</code> و <code>fetch</code> چیست؟» — مدل ذهنی می‌پرسند:</p>\n<blockquote>\n<p>«اگر روی <code>main</code> مشترک <code>rebase</code> کنی چه فاجعه‌ای رخ می‌دهد؟»\n«چطور یک باگ را با <code>bisect</code> در تاریخچهٔ ده هزار کامیتی پیدا می‌کنی؟»\n«Ruleset با Branch Protection چه فرقی دارد؟»</p>\n</blockquote>\n<p>این کتاب برای همان سطح نوشته شده است.</p>\n<div class=\"callout callout-note\"><div class=\"callout-title\">سه قطعه که تا آخر کتاب تکرار می‌شوند</div>\n<p class=\"keep-next\">تا فصل ۶ همین‌ها را با مثال می‌بینی. الان فقط معنی‌شان را بدان:</p>\n<ol>\n<li><strong>کامیت (commit)</strong> — یک عکس ثبت‌شده از <em>همه</em> فایل‌های پروژه در یک لحظه، نه فقط فهرست خطوط عوض‌شده.</li>\n<li><strong>شاخه (branch)</strong> — یک برچسب روی یک کامیت. پوشه را کپی نمی‌کند؛ فقط می‌گوید «الان این عکس، نوک کار ماست».</li>\n<li><strong>سه درخت</strong> — (الف) فایل‌هایی که در ادیتور می‌بینی، (ب) پیش‌نویس کامیت بعدی، (ج) آخرین عکس ثبت‌شده.</li>\n</ol>\n<p>هر فرمان Git فقط یکی از این‌ها را عوض می‌کند. وقتی بپرسی «این فرمان کدام را عوض کرد؟» دیگر مبهم نمی‌ماند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">📖 تاریخچه — از BitKeeper تا Git ۳.۰</span></span></h2>\n<ul>\n<li><strong>۲۰۰۵:</strong> لینوس توروالدز Git را در دو هفته ساخت؛ هستهٔ لینوکس دیگر نمی‌توانست به BitKeeper تکیه کند.</li>\n<li><strong>۲۰۰۸:</strong> GitHub متولد شد و «اجتماع روی کد» را ساخت؛ Fork و Pull Request زبان مشترک صنعت شد.</li>\n<li><strong>۲۰۱۹:</strong> <code>git switch</code> و <code>git restore</code> آمدند تا <code>checkout</code> دوچهره را بشکنند.</li>\n<li><strong>۲۰۲۵ (Git ۲.۵۱):</strong> <code>switch</code> و <code>restore</code> دیگر آزمایشی نیستند؛ reftable و SHA-256 برای مخازن جدید آماده‌اند.</li>\n<li><strong>۲۰۲۶:</strong> Git ۳.۰ در افق است — پاکسازی فرمان‌های قدیمی، hash پیش‌فرض SHA-256، و backend سریع‌تر برای میلیون‌ها ref.</li>\n<li><strong>گیت‌هاب ۲۰۲۵–۲۰۲۶:</strong> Rulesets، Immutable Releases، Copilot Coding Agent، Agent HQ، و Actions تو در تو.</li>\n</ul>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">دو مسیر در هر فصل — هیچ‌کدام را حذف نمی‌کنیم</div>\n<p>برای عوض کردن شاخه <strong>هرگز</strong> <code>checkout</code> نمی‌نویسیم: <strong><code>git switch</code> شاخه، <code>git restore</code> فایل.</strong></p>\n<p>هر مهارت را دو بار می‌بینی: فرمان در <strong>ترمینال</strong> و دکمه در <strong>VS Code</strong> (پنل Source Control و افزونهٔ GitHub Pull Requests). مفهوم را در ترمینال بفهم؛ کار روزانه را در VS Code انجام بده.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔬 Git چه چیزی نیست؟</span></span></h2>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>تصور غلط</th>\n<th>واقعیت روشن</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Git همان GitHub است</td>\n<td>Git برنامهٔ روی رایانهٔ توست. GitHub فقط یکی از سایت‌های میزبان است (GitLab و Gitea هم هستند). بدون اینترنت هم Git کار می‌کند.</td>\n</tr>\n<tr>\n<td>Git فقط پشتیبان فایل است</td>\n<td>Git علاوه بر فایل، <em>چرا</em> عوض شد (پیام کامیت) و <em>چه کسی / کی</em> را هم نگه می‌دارد.</td>\n</tr>\n<tr>\n<td>شاخه = کپی کل پروژه</td>\n<td>شاخه یک برچسب کوتاه روی یک کامیت است؛ ساختنش آنی است و پوشه را دوبرابر نمی‌کند.</td>\n</tr>\n<tr>\n<td>کامیت = فقط diff</td>\n<td>کامیت یک <strong>snapshot</strong> است: عکس کامل درخت فایل‌ها در آن لحظه. Diff بعداً از مقایسهٔ دو عکس به‌دست می‌آید.</td>\n</tr>\n</tbody>\n</table></div><div class=\"diagram\">\n<img src=\"/book/figures/dag.svg\" alt=\"گراف DAG کامیت‌ها\"/>\n<p class=\"figcap\">شکل ۱ — هر دایره یک کامیت است. پیکان به کامیت قبلی (والد) می‌رود. حلقه وجود ندارد؛ به این گراف DAG می‌گویند. شاخه فقط نام روی یکی از دایره‌هاست.</p>\n</div>\n<p><strong>DAG</strong> یعنی Directed Acyclic Graph: گراف جهت‌دار بدون دور. اگر این یک جمله را حفظ کنی، merge (دو والد) و rebase (گره‌های جدید) دیگر رمز نیستند.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🗺️ اکوسیستم ۲۰۲۶ — چه چیزی یاد بگیریم؟</span></span></h2>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>لایه</th>\n<th>انتخاب ۲۰۲۶</th>\n<th>چرا؟</th>\n<th>جایگزین</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>VCS</td>\n<td><strong>Git ۲.۵۱+</strong></td>\n<td>switch/restore پایدار، reftable</td>\n<td>Mercurial فقط میراث</td>\n</tr>\n<tr>\n<td>Host</td>\n<td><strong>GitHub</strong></td>\n<td>PR، Actions، Security، Copilot</td>\n<td>GitLab / Gitea</td>\n</tr>\n<tr>\n<td>ادیتور</td>\n<td><strong>VS Code</strong> + GitHub Pull Requests</td>\n<td>Source Control، Graph، Review داخل IDE</td>\n<td>JetBrains / Neovim</td>\n</tr>\n<tr>\n<td>CLI همراه</td>\n<td><strong>GitHub CLI (<code>gh</code>)</strong></td>\n<td>PR، Issue، Actions از ترمینال</td>\n<td>hub قدیمی</td>\n</tr>\n<tr>\n<td>کیفیت کامیت</td>\n<td><strong>Conventional Commits</strong></td>\n<td>changelog خودکار، semantic release</td>\n<td>پیام آزاد</td>\n</tr>\n<tr>\n<td>CI</td>\n<td><strong>GitHub Actions</strong></td>\n<td>OIDC، reusable workflow</td>\n<td>Jenkins میراث</td>\n</tr>\n<tr>\n<td>امنیت</td>\n<td><strong>Rulesets + signing + CodeQL</strong></td>\n<td>سیاست متمرکز، عرضهٔ قابل‌اثبات</td>\n<td>فقط branch protection کلاسیک</td>\n</tr>\n</tbody>\n</table></div><h2><span class=\"hx\"><span class=\"hx-t\">🧠 چگونه این کتاب را بخوانیم؟</span></span></h2>\n<h3><span class=\"hx\"><span class=\"hx-t\">۱. فرمان را حفظ نکن — بپرس کدام لایه عوض شد</span></span></h3>\n<p>بعد از هر فرمان از خودت بپرس: فایل روی دیسک عوض شد، پیش‌نویس کامیت عوض شد، یا تاریخچهٔ ثبت‌شده؟ (اسامی دقیق این سه لایه در فصل ۳ است.)</p>\n<h3><span class=\"hx\"><span class=\"hx-t\">۲. ترمینال و VS Code را با هم یاد بگیر</span></span></h3>\n<p>تقریباً هر کار دو شکل دارد: یک فرمان و یک دکمه. اگر فقط یکی را بلد باشی، در تیم گیر می‌کنی.</p>\n<h3><span class=\"hx\"><span class=\"hx-t\">۳. عمداً خراب کن — برگشت دارد</span></span></h3>\n<p class=\"keep-next\">حذف تاریخچهٔ ثبت‌شده سخت است، ولی حرکت اشتباه HEAD معمولاً تا حدود ۹۰ روز در <code>reflog</code> مانده. فصل ۸ دقیقاً می‌گوید کدام Undo کدام لایه را لمس می‌کند.</p>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">📘 مسیر پیشنهادی</div>\n<p><strong>هفته ۱:</strong> فصل ۱–۱۰ — مدل ذهنی + Source Control از صفر (<code>Ctrl+Shift+G</code>)<br/>\n<strong>هفته ۲:</strong> فصل ۱۱–۲۲ — همکاری واقعی روی GitHub<br/>\n<strong>هفته ۳:</strong> فصل ۲۳–۳۲ — rebase، Actions، امنیت<br/>\n<strong>هفته ۴:</strong> فصل ۳۳–۳۶ — کارگاه، اشتباهات، مصاحبه</p>\n</div>\n<div class=\"col\"><div class=\"col-title\">🚀 چک‌لیست فهم عمیق</div>\n<div class=\"checklist\">\n<ul>\n<li>می‌توانی مدل را روی کاغذ بکشی؟</li>\n<li>می‌توانی همان کار را در VS Code انجام دهی؟</li>\n<li>می‌توانی بگویی کدام فرمان تاریخچه را بازنویسی می‌کند؟</li>\n<li>می‌توانی در مصاحبه ۲ دقیقه توضیح دهی؟</li>\n</ul>\n</div>\n</div>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — Git و GitHub چه فرقی دارند؟</strong> Git موتور نسخه‌بندی توزیع‌شده روی ماشین توست. GitHub سرویس میزبانی، PR، Issue، Actions و هویت تیمی است.</p>\n<p><strong>Mid — چرا Git معمولاً از SVN سریع‌تر حس می‌شود؟</strong> چون کل تاریخچه روی رایانهٔ توست و هر فایل با هش محتوایش شناخته می‌شود. شبکه فقط وقتی لازم است که بخواهی با دیگران همگام شوی — نه برای هر مقایسه.</p>\n<p><strong>Senior — DAG یعنی چه و چرا مهم است؟</strong> تاریخچه یک خط نیست؛ یک گراف است. Merge کامیتی با دو والد می‌سازد. Rebase کامیت‌های جدید می‌سازد (هش عوض می‌شود). اگر گراف را ببینی، می‌فهمی چرا force-push روی <code>main</code> کار دیگران را می‌شکند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ جمع‌بندی و اتصال</span></span></h2>\n<ul>\n<li>Git روی رایانهٔ تو تاریخچه را با عکس لحظه‌ای و برچسب شاخه نگه می‌دارد.</li>\n<li>GitHub میزبان + صفحهٔ PR + قوانین تیم + اجرای خودکار تست است.</li>\n<li>مسیر این کتاب: <code>switch</code>/<code>restore</code>، VS Code، بعد GitHub، بعد امنیت و CI.</li>\n</ul>\n<p><strong>فصل بعد:</strong> نصب Git، نام و ایمیل، کلید SSH و امضای کامیت — تا هویت تو در تاریخچه درست ثبت شود.</p>";
export default { n, num, title, label, part, html };
